const envelope = $json.envelope;
const errors = [];

function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function isString(value) {
  return (
    typeof value === 'string' &&
    value.trim().length > 0
  );
}

function isIsoDate(value) {
  return (
    isString(value) &&
    !Number.isNaN(Date.parse(value))
  );
}

if (!isObject(envelope)) {
  errors.push('envelope_missing');
} else {
  if (envelope.schema_version !== 1) {
    errors.push('schema_version_invalid');
  }

  if (!isString(envelope.tenant_id)) {
    errors.push('tenant_id_missing');
  }

  if (!isString(envelope.channel)) {
    errors.push('channel_missing');
  }

  if (!isString(envelope.channel_account_id)) {
    errors.push('channel_account_id_missing');
  }

  if (!isString(envelope.external_event_id)) {
    errors.push('external_event_id_missing');
  }

  if (
    !isString(
      envelope.external_conversation_key,
    )
  ) {
    errors.push(
      'external_conversation_key_missing',
    );
  }

  if (
    !isString(
      envelope.customer?.external_id,
    )
  ) {
    errors.push('customer_external_id_missing');
  }

  if (!isString(envelope.message?.type)) {
    errors.push('message_type_missing');
  }

  if (!isObject(envelope.transport)) {
    errors.push('transport_missing');
  }

  if (!isIsoDate(envelope.occurred_at)) {
    errors.push('occurred_at_invalid');
  }

  if (!isIsoDate(envelope.received_at)) {
    errors.push('received_at_invalid');
  }
}

if (errors.length > 0) {
  throw new Error(
    `INGRESS_CONTRACT_INVALID: ${errors.join(', ')}`,
  );
}

return {
  json: {
    envelope,
  },
};

const rawResult = $json.result;

let result = rawResult;

if (typeof rawResult === 'string') {
  try {
    result = JSON.parse(rawResult);
  } catch {
    throw new Error(
      'INGRESS_RESULT_JSON_INVALID',
    );
  }
}

if (
  !result ||
  typeof result !== 'object' ||
  Array.isArray(result)
) {
  throw new Error(
    'INGRESS_RESULT_MISSING',
  );
}

const allowedStatuses = new Set([
  'accepted',
  'duplicate',
]);

if (!allowedStatuses.has(result.status)) {
  throw new Error(
    `INGRESS_STATUS_INVALID: ${String(
      result.status,
    )}`,
  );
}

if (result.status === 'accepted') {
  const requiredFields = [
    'message_id',
    'conversation_id',
    'customer_id',
    'conversation_state',
    'conversation_version',
    'draft_payload',
  ];

  const missing = requiredFields.filter(
    (field) =>
      result[field] === undefined ||
      result[field] === null,
  );

  if (missing.length > 0) {
    throw new Error(
      `INGRESS_RESULT_INCOMPLETE: ${missing.join(
        ', ',
      )}`,
    );
  }
}

const envelope =
  $('02 Validate Ingress Contract')
    .first()
    .json
    .envelope;

return {
  json: {
    ...result,
    envelope,
  },
};
